namespace Gizmo.Web.Reports
{
    /// <summary>
    /// Report result.
    /// </summary>
    /// <remarks>
    /// Provides access to models generated by report module.
    /// </remarks>
    public interface IReportResult
    {
        /// <summary>
        /// Gets report model.
        /// </summary>
        object ReportModel { get; }

        /// <summary>
        /// Gets additional report model.
        /// </summary>
        object? ReportModelAdditional { get; }
    }
}
